<script setup lang="ts">
import {cloudShopping,shoppingState,syncShopping} from '../services/remoteShopping'
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {showToast} from 'vant'
import {products,cartSummary} from '../services/products'
import {store,image,toggleProduct,addToCart} from '../stores/community'
import CartSheet from '../components/CartSheet.vue'
const route=useRoute(),product=computed(()=>products.find(p=>p.id===route.params.id)),cartOpen=ref(false),slide=ref(0)
const cart=computed(()=>cartSummary(store.cart))
watch(()=>route.params.id,()=>slide.value=0)
async function add(){if(!product.value)return;if((store.cart[product.value.id]||0)>=99){showToast('单件商品最多添加 99 件');return}if(await addToCart(product.value.id))showToast(cloudShopping?'已加入云端购物清单':'已加入本地购物清单')}
</script>
<template><main class="product-page"><header class="product-nav"><RouterLink to="/goods" aria-label="返回好物"><van-icon name="arrow-left"/></RouterLink><h1>好物详情</h1><button aria-label="查看购物清单" @click="cartOpen=true"><van-badge :content="cart.count||undefined" max="99"><van-icon name="shopping-cart-o"/></van-badge></button></header><p v-if="shoppingState.error" role="alert">{{shoppingState.error}} <button @click="syncShopping().catch(()=>{})">刷新重试</button></p><template v-if="product"><div class="product-gallery"><van-swipe :key="product.id" :loop="false" indicator-color="#9b79b4" @change="i=>slide=i"><van-swipe-item v-for="(src,index) in product.gallery" :key="src"><img :src="image(src)" :alt="product.name+' 商品图片 '+(index+1)"/></van-swipe-item></van-swipe><span class="gallery-count">{{slide+1}} / {{product.gallery.length}}</span><span class="sample-mark">示例商品</span></div><section class="product-intro"><div class="price-line"><strong><small>¥</small>{{product.price.toFixed(2)}}</strong><del>¥{{product.originalPrice.toFixed(2)}}</del><span>示例销量 {{product.sold.toLocaleString()}}</span></div><div class="product-labels"><span>好物精选</span><span>{{product.fit}}</span></div><h2>{{product.name}}</h2><p>{{product.subtitle}}</p><div class="rating-line"><span><van-icon name="star"/> {{product.rating.toFixed(1)}} 分</span><small>示例评分 · {{product.reviews}} 条示例评价</small></div></section><section class="product-section"><h2>关于这件小好物</h2><p>{{product.description}}</p><dl><div><dt>适用宠物</dt><dd>{{product.fit}}</dd></div><div><dt>商品规格</dt><dd>{{product.spec}}</dd></div></dl></section><section class="product-section"><h2><van-icon name="bulb-o"/> 选购与使用提醒</h2><ol><li v-for="tip in product.tips" :key="tip">{{tip}}</li></ol></section><section class="product-section demo-review"><div><h2>评价展示</h2><span>示例</span></div><p>当前尚未接入真实用户评价。评分、销量与评价数量仅用于演示界面，不代表真实购买反馈。</p></section><p class="product-disclaimer">图片、价格与商品信息来自交互原型。<br>当前不支持真实购买、支付和物流。</p><div class="product-action"><button class="save-product" :class="{saved:store.savedProducts.includes(product.id)}" :aria-label="store.savedProducts.includes(product.id)?'取消收藏':'收藏商品'" :aria-pressed="store.savedProducts.includes(product.id)" @click="toggleProduct(product.id)"><van-icon :name="store.savedProducts.includes(product.id)?'like':'like-o'"/><span>{{store.savedProducts.includes(product.id)?'已收藏':'收藏'}}</span></button><button class="view-cart" @click="cartOpen=true"><van-icon name="shopping-cart-o"/><span>清单{{cart.count?' · '+cart.count:''}}</span></button><van-button round color="linear-gradient(120deg,#e68068,#d0614e)" @click="add">加入购物清单</van-button></div></template><van-empty v-else description="没有找到这件好物"><RouterLink to="/goods" class="primary-link">返回好物页</RouterLink></van-empty><CartSheet v-model:show="cartOpen"/></main></template>
<style scoped>.product-page{padding:0 18px 115px;color:#352943}.product-nav{display:flex;align-items:center;justify-content:space-between;gap:12px;height:69px}.product-nav h1{font-size:17px;font-weight:650;letter-spacing:0}.product-nav>a,.product-nav>button{display:grid;place-items:center;width:36px;height:36px;border:1px solid white;border-radius:50%;background:#ffffffaa;color:#8b7598;font-size:20px}.product-gallery{position:relative;overflow:hidden;border-radius:25px;border:1px solid white;background:#f6eef9;margin-bottom:16px}.product-gallery img{width:100%;aspect-ratio:1;display:block;object-fit:cover}.gallery-count{position:absolute;bottom:12px;right:12px;background:#ffffffc9;backdrop-filter:blur(10px);border:1px solid white;padding:4px 9px;border-radius:15px;font-size:10px;color:#8e779b}.sample-mark{position:absolute;top:13px;left:13px;padding:4px 9px;border-radius:15px;background:#ffffffc9;font-size:9px;color:#9b80ab}.product-intro,.product-section{background:#ffffffc2;border:1px solid white;border-radius:22px;padding:18px 16px;margin-bottom:14px}.price-line{display:flex;align-items:baseline;gap:9px}.price-line>strong{font-size:29px;font-weight:650;color:#cc7157;letter-spacing:-.8px}.price-line>strong small{font-size:16px;margin-right:3px}.price-line del{font-size:11px;color:#b7a1c1}.price-line>span{margin-left:auto;font-size:9px;color:#a990b5}.product-labels{display:flex;gap:6px;margin:12px 0}.product-labels span{padding:3px 7px;border-radius:6px;font-size:9px;background:#f0e5f7;color:#a07bb5}.product-labels span:first-child{background:#fae7df;color:#ce8a72}.product-intro h2{font-size:19px;line-height:1.6}.product-intro>p{font-size:11px;color:#a58aB3;margin-top:5px}.rating-line{display:flex;align-items:center;gap:9px;padding-top:15px;margin-top:16px;border-top:1px solid #f0e6f5}.rating-line>span{font-size:12px;color:#bc9967}.rating-line small{font-size:9px;color:#ae97ba}.product-section h2{font-size:14px;font-weight:600;margin-bottom:12px;display:flex;gap:6px;align-items:center}.product-section h2>.van-icon{color:#b49a72}.product-section>p{font-size:12px;color:#91789f;line-height:1.9}.product-section dl{margin:15px 0 0;padding:13px;background:#f7f1fb;border-radius:13px;display:flex;flex-direction:column;gap:10px}.product-section dl>div{display:flex;gap:12px;font-size:11px}.product-section dt{white-space:nowrap;color:#ac94b8}.product-section dd{margin:0;color:#8a7099;flex:1;text-align:right}.product-section ol{list-style:none;counter-reset:tips;margin:0;padding:0}.product-section li{counter-increment:tips;position:relative;padding-left:25px;font-size:11px;line-height:1.9;color:#967eA4;margin-bottom:9px}.product-section li:before{content:counter(tips);position:absolute;left:0;top:2px;display:grid;place-items:center;width:17px;height:17px;border-radius:6px;background:#f1e8f7;color:#b295c2;font-size:9px}.product-section li:last-child{margin-bottom:0}.demo-review>div{display:flex;justify-content:space-between;gap:10px}.demo-review>div>span{font-size:9px;color:#b29abe}.demo-review>p{font-size:10px}.product-disclaimer{font-size:9px;color:#b29abe;text-align:center;line-height:1.9;margin:20px 0}.product-action{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:var(--app-width);display:flex;align-items:center;gap:15px;padding:13px 18px calc(13px + env(safe-area-inset-bottom,0px));background:#fffafdf0;backdrop-filter:blur(18px);border-top:1px solid white;border-radius:22px 22px 0 0;box-shadow:0 -6px 26px #9c7cab12;z-index:20}.product-action>button:not(.van-button){display:flex;flex-direction:column;align-items:center;gap:5px;background:transparent;border:0;padding:0 4px;color:#9e86ad;font-size:10px;white-space:nowrap}.product-action>button:not(.van-button) .van-icon{font-size:21px}.product-action .save-product.saved{color:#d77c89}.product-action>.van-button{flex:1;font-size:12px;font-weight:600;height:44px}</style>
